import{_ as e,r as a,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Перенаправления - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как перенаправить на другую страницу или URL.","frontmatter":{"subtitle":"Узнайте, как перенаправить на другую страницу или URL."},"headers":[{"level":2,"title":"Перенаправление на CMS-страницу","slug":"перенаправление-на-cms-страницу","link":"#перенаправление-на-cms-страницу","children":[]},{"level":2,"title":"Перенаправления в Twig","slug":"перенаправления-в-twig","link":"#перенаправления-в-twig","children":[]},{"level":2,"title":"Перенаправления в AJAX","slug":"перенаправления-в-ajax","link":"#перенаправления-в-ajax","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/cms/features/redirects.md","filePath":"3.x/ru/cms/features/redirects.md"}'),i={name:"3.x/ru/cms/features/redirects.md"};function r(k,n,g,d,m,h){const t=a("pre-heading"),p=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"Перенаправления",-1)),s(p),n[1]||(n[1]=u(`<p>В некоторых случаях вам может потребоваться перенаправить пользователя на новую страницу после отправки формы или любого AJAX-запроса.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSignup<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Email<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Sign Up
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Внутри вашего <a href="./../ajax/handlers.html">AJAX-обработчика</a> вы можете вернуть <a href="./../../extend/services/response-view.html">тип ответа</a> <code>Redirect</code>, где метод <code>to</code> принимает относительный или абсолютный URL (первый аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSignup</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/signup-complete&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы можете использовать метод <code>refresh</code> для обновления текущей страницы. Также поддерживается использование <a href="./flash-messages.html">flash-сообщений</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSignup</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Signup complete!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">refresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="перенаправление-на-cms-страницу"><a href="#перенаправление-на-cms-страницу" class="header-anchor">#</a> Перенаправление на CMS-страницу</h2><p>Фасад <code>Cms</code> и метод <code>redirect</code> могут использоваться для перенаправления на конкретную CMS-страницу (первый аргумент) с необязательными параметрами маршрута (второй аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirect</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">redirect</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blog/post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;foobar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы можете использовать метод <code>pageUrl</code> для получения URL в виде строки.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$postPage</span> <span class="token operator">=</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">pageUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blog/post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;foobar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="перенаправления-в-twig"><a href="#перенаправления-в-twig" class="header-anchor">#</a> Перенаправления в Twig</h2><p><a href="./../../markup/function/redirect.html">Twig-функция <code>redirect()</code></a> может использоваться для перенаправления пользователя из разметки страницы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSignup</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;success&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Эта функция принимает URL или имя CMS-страницы.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> success <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> redirect<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>/signup-complete<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="перенаправления-в-ajax"><a href="#перенаправления-в-ajax" class="header-anchor">#</a> Перенаправления в AJAX</h2><p><a href="./../ajax/introduction.html">AJAX-фреймворк</a> поддерживает перенаправления с помощью атрибута <code>data-request-redirect</code>. Значение атрибута должно указывать URL для перенаправления после успешного завершения AJAX-запроса.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-redirect</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/signup-complete<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Save and Redirect
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a href="./../ajax/turbo-router.html">Turbo-маршрутизатор</a> поддерживает исторические перенаправления с помощью атрибута <code>data-browser-redirect-back</code>. Атрибут может быть прикреплён к любой гиперссылке или элементу AJAX-запроса, переопределяя ответ перенаправления, и срабатывает только при наличии предыдущего состояния истории браузера.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRedirect<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-browser-redirect-back</span><span class="token punctuation">&gt;</span></span>
    Save and Back
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Значение атрибута также может использоваться с гиперссылками.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/home<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-browser-redirect-back</span><span class="token punctuation">&gt;</span></span>
    Go Back
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block warning"><p>Атрибут <code>data-browser-redirect-back</code> следует использовать в сочетании с традиционным перенаправлением в качестве резервного адреса.</p></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../markup/function/redirect.html">Twig-функция redirect</a></li><li><a href="./../../extend/services/response-view.html">Ответы и представления</a></li></ul></div>`,26))])}const w=e(i,[["render",r]]);export{v as __pageData,w as default};
